var _markdown = "\n\n`vc` · 扩展 `CLEO` · 需 CLEO\n\nChar / Car / World / Weapon / Camera 等。\n\n写法见 [Lua](/docs/cleo/syntax) / [Redux](/docs/cleo/syntax-redux)。\n\n## 载具档位数 [#载具档位数]\n\n<Opcode id=\"0AB7\" name=\"GET_CAR_NUMBER_OF_GEARS\" member=\"Car.GetNumberOfGears\">\n  载具档位数。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0AB7 GET_CAR_NUMBER_OF_GEARS\n      in: self\n      out: numGear\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local n = getCarNumberOfGears(car)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const numGear = Car.getNumberOfGears(self)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 当前档位 [#当前档位]\n\n<Opcode id=\"0AB8\" name=\"GET_CAR_CURRENT_GEAR\" member=\"Car.GetCurrentGear\">\n  当前档位。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0AB8 GET_CAR_CURRENT_GEAR\n      in: self\n      out: gear\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local gear = getCarCurrentGear(car)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const gear = Car.getCurrentGear(self)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 车灯是否开 [#车灯是否开]\n\n<Opcode id=\"0ABD\" name=\"IS_CAR_LIGHTS_ON\" member=\"Car.IsLightsOn\">\n  车灯是否开。用在 `if` 里。（VC JSON 名；SA 侧常见警笛名，以本游戏 JSON 为准。）\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0ABD IS_CAR_LIGHTS_ON\n      in: self\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      if isCarLightsOn(car) then\n      end\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      if (Car.isLightsOn(self)) {}\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 引擎是否开 [#引擎是否开]\n\n<Opcode id=\"0ABE\" name=\"IS_CAR_ENGINE_ON\" member=\"Car.IsEngineOn\">\n  引擎是否开。用在 `if` 里。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0ABE IS_CAR_ENGINE_ON\n      in: self\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      if isCarEngineOn(car) then\n      end\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      if (Car.isEngineOn(self)) {}\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 开/关引擎 [#开关引擎]\n\n<Opcode id=\"0ABF\" name=\"SET_CAR_ENGINE_ON\" member=\"Car.SetEngineOn\">\n  开/关引擎。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0ABF SET_CAR_ENGINE_ON\n      in: self, state\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      setCarEngineOn(car, true)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Car.setEngineOn(self, state)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 作弊刷车 [#作弊刷车]\n\n<Opcode id=\"0ADD\" name=\"SPAWN_VEHICLE_BY_CHEATING\" member=\"World.SpawnVehicleByCheating\">\n  在玩家前方刷一辆指定模型车（无需预加载）。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0ADD SPAWN_VEHICLE_BY_CHEATING\n      in: modelId\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      spawnVehicleByCheating(modelId)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      World.spawnVehicleByCheating(modelId)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 球内随机角色 [#球内随机角色]\n\n<Opcode id=\"0AE1\" name=\"GET_RANDOM_CHAR_IN_SPHERE_NO_SAVE_RECURSIVE\" member=\"World.GetRandomCharInSphereNoSaveRecursive\">\n  球内递归取角色；`findNext` 继续枚举。用在 `if` 里。经典别名 `05EF`。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0AE1 GET_RANDOM_CHAR_IN_SPHERE_NO_SAVE_RECURSIVE\n      in: x, y, z, radius, findNext, skipDead\n      out: handle\n      // 经典别名 05EF\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local ped = getRandomCharInSphereNoSaveRecursive(x, y, z, 20.0, false, true)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const handle = World.getRandomCharInSphereNoSaveRecursive(x, y, z, radius, findNext, skipDead)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 球内随机载具 [#球内随机载具]\n\n<Opcode id=\"0AE2\" name=\"GET_RANDOM_CAR_IN_SPHERE_NO_SAVE_RECURSIVE\" member=\"World.GetRandomCarInSphereNoSaveRecursive\">\n  球内递归取载具。经典别名 `05F0`。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0AE2 GET_RANDOM_CAR_IN_SPHERE_NO_SAVE_RECURSIVE\n      in: x, y, z, radius, findNext, skipWrecked\n      out: handle\n      // 经典别名 05F0\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local car = getRandomCarInSphereNoSaveRecursive(x, y, z, 30.0, false, true)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const handle = World.getRandomCarInSphereNoSaveRecursive(x, y, z, radius, findNext, skipWrecked)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 球内随机物体 [#球内随机物体]\n\n<Opcode id=\"0AE3\" name=\"GET_RANDOM_OBJECT_IN_SPHERE_NO_SAVE_RECURSIVE\" member=\"World.GetRandomObjectInSphereNoSaveRecursive\">\n  球内递归取物体。经典别名 `05F1`。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0AE3 GET_RANDOM_OBJECT_IN_SPHERE_NO_SAVE_RECURSIVE\n      in: x, y, z, radius, findNext\n      out: handle\n      // 经典别名 05F1\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local obj = getRandomObjectInSphereNoSaveRecursive(x, y, z, 10.0, false)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const handle = World.getRandomObjectInSphereNoSaveRecursive(x, y, z, radius, findNext)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 武器类型转模型 [#武器类型转模型]\n\n<Opcode id=\"0604\" name=\"GET_WEAPONTYPE_MODEL\" member=\"Weapon.GetModel\">\n  武器类型 → 模型 id。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0604 GET_WEAPONTYPE_MODEL\n      in: weaponType\n      out: modelId\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local model = getWeapontypeModel(weaponType)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const modelId = Weapon.getModel(weaponType)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 模型转武器类型 [#模型转武器类型]\n\n<Opcode id=\"0605\" name=\"GET_WEAPONTYPE_FOR_MODEL\" member=\"Weapon.GetTypeForModel\">\n  武器模型 id → 武器类型。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0605 GET_WEAPONTYPE_FOR_MODEL\n      in: modelId\n      out: weaponType\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local w = getWeapontypeForModel(modelId)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const weaponType = Weapon.getTypeForModel(modelId)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 相机宽屏模式 [#相机宽屏模式]\n\n<Opcode id=\"0603\" name=\"IS_CAMERA_IN_WIDESCREEN_MODE\" member=\"Camera.IsInWidescreenMode\">\n  相机是否宽屏模式。用在 `if` 里。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0603 IS_CAMERA_IN_WIDESCREEN_MODE\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      if isCameraInWidescreenMode() then\n      end\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      if (Camera.isInWidescreenMode()) {}\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 播放动画 [#播放动画]\n\n<Opcode id=\"0673\" name=\"PLAY_ANIMATION\" member=\"Char.PlayAnimation\">\n  角色播放动画组内动作。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0673 PLAY_ANIMATION\n      in: self, groupId, animId, blend\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      playAnimation(ped, groupId, animId, 4.0)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Char.playAnimation(self, groupId, animId, blend)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 画阴影 [#画阴影]\n\n<Opcode id=\"016F\" name=\"DRAW_SHADOW\" member=\"Fx.DrawShadow\">\n  当前帧画阴影。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      016F DRAW_SHADOW\n      in: textureType, x, y, z, angle, size, intensity, r, g, b\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      drawShadow(tex, x, y, z, 0.0, 1.0, 100, 0, 0, 0)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Fx.drawShadow(textureType, x, y, z, angle, size, intensity, r, g, b)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 载具模型名 [#载具模型名]\n\n<Opcode id=\"0ADB\" name=\"GET_NAME_OF_VEHICLE_MODEL\" member=\"Streaming.GetNameOfVehicleModel\">\n  载具模型 → 名字串。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0ADB GET_NAME_OF_VEHICLE_MODEL\n      in: modelId\n      out: carName\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local name = getNameOfVehicleModel(modelId)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const carName = Streaming.getNameOfVehicleModel(modelId)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n";
